           ev("diagnosis", -6.75, "years", "First major depressive episode after the ovarian cancer diagnosis; sertraline helped for years", "approx"),
           ev("diagnosis", -9, "months", "Cancer recurrence: recurrent major depression and new generalised anxiety disorder"),
