           ev("exposure_start", 0, "days", "Bone marrow transplant; 34 days in a germ-free unit, no antipsychotics"),
           ev("cointervention", 0, "days", "Methotrexate and ciclosporin to prevent graft-versus-host disease"),
           ev("cointervention", 3, "weeks", "Early graft-versus-host disease: tacrolimus replaced ciclosporin"),
